WHERE [object_id] = 1525580473 
 AND [owner_scope_local_id] = 1
SET @sync_row_count = 0; DELETE [dbo].[Applications] FROM [dbo].[Applications] [base] LEFT JOIN [DataSync].[Applications_dss_tracking] [side] ON [base].[applicationID] = [side].[applicationID] WHERE ((CASE WHEN [side].[local_create_peer_timestamp] IS NOT NULL AND [side].[local_update_peer_timestamp] > @marker_local_update_peer_timestamp 
