SET @sync_row_count = 0; DELETE [dbo].[Clients] FROM [dbo].[Clients] [base] LEFT JOIN [DataSync].[Clients_dss_tracking] [side] ON [base].[clientId] = [side].[clientId] WHERE ((CASE WHEN [side].[local_create_peer_timestamp] IS NOT NULL AND [side].[local_update_peer_timestamp] > @marker_local_update_peer_timestamp 
