FROM [DataSync].[provision_marker_dss]
WHERE [object_id] = 1666104976 
 AND [owner_scope_local_id] = 1

SELECT (CASE WHEN [side].[local_create_peer_timestamp] IS NOT NULL 
THEN [side].[ID]
ELSE [base].[ID] END) 
as [ID], 
[base].[Building Number], [base].[Owner Number], [base].[Address 1], [base].[Address 2], [base].[Agent Name], [base].[Block Number], [base].[Lot Number], [base].[Section Number], [base].[Multiple Dwelling Registration Number], [base].[RSA], [base].[Senior Citizen Number], [base].[Superintendant Name], [base].[Superintendant Phone], [base].[Real Estate Taxes], [base].[Mortgage Interest], [base].[Total Shares], [base].[MasterAccount], [base].[AuthRep], [base].[FaxNumber], [base].[AuthCode], [base].[email], [base].[RentChangeMCI], [base].[RentChangeHardship], [base].[AgentIs], [base].[clientId], [base].[DHCRLow], [base].[DHCRHigh], [base].[DHCRStreetName], [base].[DHCRStreetSuffix], [base].[DHCRCity], [base].[DHCRZip], [base].[DHCRCounty], [base].[DHCRMunicipality], [base].[DHCRLow2], [base].[DHCRHigh2], [base].[DHCRStreetName2], [base].[DHCRStreetSuffix2], [base].[DHCRCity2], [base].[DHCRZip2], [base].[DHCRCounty2], [base].[DHCRMunicipality2], [base].[DHCRLow3], [base].[DHCRHigh3], [base].[DHCRStreetName3], [base].[DHCRStreetSuffix3], [base].[DHCRCity3], [base].[DHCRZip3], [base].[DHCRCounty3], [base].[DHCRMunicipality3], [base].[CoopCondo], [base].[NonEvictionDate], [base].[EvictionDate], [base].[AcceptedForFilingDate], (CASE WHEN [side].[local_create_peer_timestamp] IS NOT NULL 
