EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [DataSync].[pm_Charges_dss_bulkupdate_f7856053-5d5c-4a36-82ff-3f507b905306]
	@sync_min_timestamp BigInt,
	@sync_scope_local_id Int,
	@changeTable [DataSync].[pm_Charges_dss_BulkType_f7856053-5d5c-4a36-82ff-3f507b905306] READONLY
AS
BEGIN
DECLARE @marker_create_scope_local_id INT
DECLARE @marker_scope_create_peer_timestamp BIGINT
DECLARE @marker_scope_create_peer_key INT
DECLARE @marker_local_create_peer_timestamp BIGINT
DECLARE @marker_local_create_peer_key INT
DECLARE @marker_state INT
SELECT TOP 1 @marker_create_scope_local_id = [provision_scope_local_id], @marker_local_create_peer_timestamp = [provision_timestamp], @marker_local_create_peer_key = [provision_local_peer_key], @marker_scope_create_peer_timestamp = [provision_scope_peer_timestamp], @marker_scope_create_peer_key = [provision_scope_peer_key], @marker_state = [state]
FROM [DataSync].[provision_marker_dss]
WHERE [object_id] = 318624178 
 AND [owner_scope_local_id] = 0

DECLARE @marker_update_scope_local_id INT
DECLARE @marker_scope_update_peer_timestamp BIGINT
DECLARE @marker_scope_update_peer_key INT
DECLARE @marker_local_update_peer_timestamp BIGINT
DECLARE @marker_local_update_peer_key INT
SELECT TOP 1 @marker_update_scope_local_id = [provision_scope_local_id], @marker_local_update_peer_timestamp = [provision_timestamp], @marker_local_update_peer_key = [provision_local_peer_key], @marker_scope_update_peer_timestamp = [provision_scope_peer_timestamp], @marker_scope_update_peer_key = [provision_scope_peer_key]
FROM [DataSync].[provision_marker_dss]
WHERE [object_id] = 318624178 
 AND [owner_scope_local_id] = 1
-- use a temp table to store the list of PKs that successfully got updated
declare @changed TABLE ([Charge Number] bigint, PRIMARY KEY ([Charge Number]));

SET IDENTITY_INSERT [dbo].[pm_Charges] ON;
-- update the base table
MERGE [dbo].[pm_Charges] AS base USING
-- join done here against the side table to get the local timestamp for concurrency check
(SELECT p.*, t.update_scope_local_id, t.scope_update_peer_key, t.local_update_peer_timestamp FROM @changeTable p LEFT JOIN [DataSync].[pm_Charges_dss_tracking] t ON p.[Charge Number] = t.[Charge Number]) as changes ON changes.[Charge Number] = base.[Charge Number]
WHEN MATCHED AND (changes.update_scope_local_id = @sync_scope_local_id AND changes.scope_update_peer_key = changes.sync_update_peer_key) OR changes.local_update_peer_timestamp <= @sync_min_timestamp-- No tracking record exists
OR (changes.update_scope_local_id IS NULL AND changes.scope_update_peer_key IS NULL AND changes.local_update_peer_timestamp IS NULL) 
 THEN
UPDATE SET [Building Number] = changes.[Building Number], [Tenant Number] = changes.[Tenant Number], [Sequence Number] = changes.[Sequence Number], [Charge Code] = changes.[Charge Code], [Type] = changes.[Type], [Amount] = changes.[Amount], [Arrears] = changes.[Arrears], [Paid] = changes.[Paid], [Starting Date] = changes.[Starting Date], [Ending Date] = changes.[Ending Date], [Future Amount] = changes.[Future Amount], [Future Date] = changes.[Future Date], [History Date] = changes.[History Date], [Comment] = changes.[Comment], [OnBill] = changes.[OnBill], [ChargeToTenant] = changes.[ChargeToTenant], [LegalRent] = changes.[LegalRent], [ShowOnBill] = changes.[ShowOnBill], [clientId] = changes.[clientId], [chargeID] = changes.[chargeID]
OUTPUT INSERTED.[Charge Number] into @changed; -- populates the temp table with successful PKs

SET IDENTITY_INSERT [dbo].[pm_Charges] OFF;
UPDATE side SET
update_scope_local_id = @sync_scope_local_id, 
scope_update_peer_key = changes.sync_update_peer_key, 
scope_update_peer_timestamp = changes.sync_update_peer_timestamp,
local_update_peer_key = 0
FROM 
[DataSync].[pm_Charges_dss_tracking] side JOIN 
(SELECT p.[Charge Number], p.sync_update_peer_timestamp, p.sync_update_peer_key, p.sync_create_peer_key, p.sync_create_peer_timestamp FROM @changed t JOIN @changeTable p ON p.[Charge Number] = t.[Charge Number]) as changes ON changes.[Charge Number] = side.[Charge Number]
SELECT [Charge Number] FROM @changeTable t WHERE NOT EXISTS (SELECT [Charge Number] from @changed i WHERE t.[Charge Number] = i.[Charge Number])
END' 
END
