FROM [DataSync].[provision_marker_dss]
WHERE [object_id] = 318624178 
 AND [owner_scope_local_id] = 1

SELECT (CASE WHEN [side].[local_create_peer_timestamp] IS NOT NULL 
THEN [side].[Charge Number]
ELSE [base].[Charge Number] END) 
as [Charge Number], 
[base].[Building Number], [base].[Tenant Number], [base].[Sequence Number], [base].[Charge Code], [base].[Type], [base].[Amount], [base].[Arrears], [base].[Paid], [base].[Starting Date], [base].[Ending Date], [base].[Future Amount], [base].[Future Date], [base].[History Date], [base].[Comment], [base].[OnBill], [base].[ChargeToTenant], [base].[LegalRent], [base].[ShowOnBill], [base].[clientId], [base].[chargeID], (CASE WHEN [side].[local_create_peer_timestamp] IS NOT NULL 
