 AND [owner_scope_local_id] = 1
-- use a temp table to store the list of PKs that successfully got updated
declare @changed TABLE ([hist_chg_id] bigint, PRIMARY KEY ([hist_chg_id]));

SET IDENTITY_INSERT [dbo].[pm_HistChg] ON;
-- update the base table
MERGE [dbo].[pm_HistChg] AS base USING
-- join done here against the side table to get the local timestamp for concurrency check
(SELECT p.*, t.update_scope_local_id, t.scope_update_peer_key, t.local_update_peer_timestamp FROM @changeTable p LEFT JOIN [DataSync].[pm_HistChg_dss_tracking] t ON p.[hist_chg_id] = t.[hist_chg_id]) as changes ON changes.[hist_chg_id] = base.[hist_chg_id]
WHEN MATCHED AND (changes.update_scope_local_id = @sync_scope_local_id AND changes.scope_update_peer_key = changes.sync_update_peer_key) OR changes.local_update_peer_timestamp <= @sync_min_timestamp-- No tracking record exists
OR (changes.update_scope_local_id IS NULL AND changes.scope_update_peer_key IS NULL AND changes.local_update_peer_timestamp IS NULL) 
 THEN
UPDATE SET [Building Number] = changes.[Building Number], [Tenant Number] = changes.[Tenant Number], [Sequence Number] = changes.[Sequence Number], [Charge Number] = changes.[Charge Number], [Date] = changes.[Date], [Code] = changes.[Code], [Amount] = changes.[Amount], [Arrears] = changes.[Arrears], [clientId] = changes.[clientId]
OUTPUT INSERTED.[hist_chg_id] into @changed; -- populates the temp table with successful PKs

SET IDENTITY_INSERT [dbo].[pm_HistChg] OFF;
UPDATE side SET
update_scope_local_id = @sync_scope_local_id, 
scope_update_peer_key = changes.sync_update_peer_key, 
scope_update_peer_timestamp = changes.sync_update_peer_timestamp,
local_update_peer_key = 0
FROM 
[DataSync].[pm_HistChg_dss_tracking] side JOIN 
(SELECT p.[hist_chg_id], p.sync_update_peer_timestamp, p.sync_update_peer_key, p.sync_create_peer_key, p.sync_create_peer_timestamp FROM @changed t JOIN @changeTable p ON p.[hist_chg_id] = t.[hist_chg_id]) as changes ON changes.[hist_chg_id] = side.[hist_chg_id]
