DECLARE @changed TABLE ([ID] bigint, PRIMARY KEY ([ID]));

SET IDENTITY_INSERT [dbo].[pm_Histmast] ON;
-- update/insert into the base table
MERGE [dbo].[pm_Histmast] AS base USING
-- join done here against the side table to get the local timestamp for concurrency check
(SELECT p.*, t.local_update_peer_timestamp FROM @changeTable p LEFT JOIN [DataSync].[pm_Histmast_dss_tracking] t ON p.[ID] = t.[ID]) AS changes ON changes.[ID] = base.[ID]
WHEN NOT MATCHED BY TARGET AND changes.local_update_peer_timestamp <= @sync_min_timestamp OR changes.local_update_peer_timestamp IS NULL THEN
INSERT ([Building Number], [Tenant Number], [Sequence Number], [Tenant Name], [Apartment], [clientId], [ID]) VALUES (changes.[Building Number], changes.[Tenant Number], changes.[Sequence Number], changes.[Tenant Name], changes.[Apartment], changes.[clientId], changes.[ID])
OUTPUT INSERTED.[ID] INTO @changed; -- populates the temp table with successful PKs

SET IDENTITY_INSERT [dbo].[pm_Histmast] OFF;
UPDATE side SET
update_scope_local_id = @sync_scope_local_id, 
scope_update_peer_key = changes.sync_update_peer_key, 
scope_update_peer_timestamp = changes.sync_update_peer_timestamp,
local_update_peer_key = 0,
create_scope_local_id = @sync_scope_local_id,
scope_create_peer_key = changes.sync_create_peer_key,
scope_create_peer_timestamp = changes.sync_create_peer_timestamp,
local_create_peer_key = 0
FROM 
[DataSync].[pm_Histmast_dss_tracking] side JOIN 
(SELECT p.[ID], p.sync_update_peer_timestamp, p.sync_update_peer_key, p.sync_create_peer_key, p.sync_create_peer_timestamp FROM @changed t JOIN @changeTable p ON p.[ID] = t.[ID]) AS changes ON changes.[ID] = side.[ID]
SELECT [ID] FROM @changeTable t WHERE NOT EXISTS (SELECT [ID] from @changed i WHERE t.[ID] = i.[ID])
END' 
END
