FROM [DataSync].[provision_marker_dss]
WHERE [object_id] = 91147370 
 AND [owner_scope_local_id] = 1
-- use a temp table to store the list of PKs that successfully got updated/inserted
declare @changed TABLE ([hist_pay_id] bigint, PRIMARY KEY ([hist_pay_id]));
DELETE [dbo].[pm_HistPay] 
OUTPUT DELETED.[hist_pay_id] INTO @changed FROM [dbo].[pm_HistPay] base JOIN
(SELECT p.*, t.update_scope_local_id, t.scope_update_peer_key, t.local_update_peer_timestamp FROM @changeTable p  LEFT JOIN [DataSync].[pm_HistPay_dss_tracking] t ON p.[hist_pay_id] = t.[hist_pay_id]) as changes ON changes.[hist_pay_id] = base.[hist_pay_id] WHERE (changes.update_scope_local_id = @sync_scope_local_id AND changes.scope_update_peer_key = changes.sync_update_peer_key) OR changes.local_update_peer_timestamp <= @sync_min_timestamp

