AS
BEGIN
-- use a temp table to store the list of PKs that successfully got updated/inserted
DECLARE @changed TABLE ([Line Number] bigint, PRIMARY KEY ([Line Number]));

SET IDENTITY_INSERT [dbo].[pm_Improvements] ON;
-- update/insert into the base table
MERGE [dbo].[pm_Improvements] AS base USING
-- join done here against the side table to get the local timestamp for concurrency check
(SELECT p.*, t.local_update_peer_timestamp FROM @changeTable p LEFT JOIN [DataSync].[pm_Improvements_dss_tracking] t ON p.[Line Number] = t.[Line Number]) AS changes ON changes.[Line Number] = base.[Line Number]
WHEN NOT MATCHED BY TARGET AND changes.local_update_peer_timestamp <= @sync_min_timestamp OR changes.local_update_peer_timestamp IS NULL THEN
INSERT ([Building Number], [Tenant Number], [Date], [Line Number], [Type], [Brand], [model], [size], [Color], [Vendor], [Cost], [Battery], [clientId]) VALUES (changes.[Building Number], changes.[Tenant Number], changes.[Date], changes.[Line Number], changes.[Type], changes.[Brand], changes.[model], changes.[size], changes.[Color], changes.[Vendor], changes.[Cost], changes.[Battery], changes.[clientId])
OUTPUT INSERTED.[Line Number] INTO @changed; -- populates the temp table with successful PKs

SET IDENTITY_INSERT [dbo].[pm_Improvements] OFF;
UPDATE side SET
update_scope_local_id = @sync_scope_local_id, 
scope_update_peer_key = changes.sync_update_peer_key, 
scope_update_peer_timestamp = changes.sync_update_peer_timestamp,
local_update_peer_key = 0,
create_scope_local_id = @sync_scope_local_id,
scope_create_peer_key = changes.sync_create_peer_key,
scope_create_peer_timestamp = changes.sync_create_peer_timestamp,
local_create_peer_key = 0
FROM 
[DataSync].[pm_Improvements_dss_tracking] side JOIN 
(SELECT p.[Line Number], p.sync_update_peer_timestamp, p.sync_update_peer_key, p.sync_create_peer_key, p.sync_create_peer_timestamp FROM @changed t JOIN @changeTable p ON p.[Line Number] = t.[Line Number]) AS changes ON changes.[Line Number] = side.[Line Number]
SELECT [Line Number] FROM @changeTable t WHERE NOT EXISTS (SELECT [Line Number] from @changed i WHERE t.[Line Number] = i.[Line Number])
END' 
END
