ELSE [base].[Line Number] END) 
as [Line Number], 
[base].[Building Number], [base].[Tenant Number], [base].[Date], [base].[Type], [base].[Brand], [base].[model], [base].[size], [base].[Color], [base].[Vendor], [base].[Cost], [base].[Battery], [base].[clientId], (CASE WHEN [side].[local_create_peer_timestamp] IS NOT NULL 
