IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[DataSync].[pm_Maintenance_dss_bulkupdate_f7856053-5d5c-4a36-82ff-3f507b905306]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [DataSync].[pm_Maintenance_dss_bulkupdate_f7856053-5d5c-4a36-82ff-3f507b905306]
	@sync_min_timestamp BigInt,
	@sync_scope_local_id Int,
	@changeTable [DataSync].[pm_Maintenance_dss_BulkType_f7856053-5d5c-4a36-82ff-3f507b905306] READONLY
AS
BEGIN
DECLARE @marker_create_scope_local_id INT
DECLARE @marker_scope_create_peer_timestamp BIGINT
DECLARE @marker_scope_create_peer_key INT
DECLARE @marker_local_create_peer_timestamp BIGINT
DECLARE @marker_local_create_peer_key INT
DECLARE @marker_state INT
SELECT TOP 1 @marker_create_scope_local_id = [provision_scope_local_id], @marker_local_create_peer_timestamp = [provision_timestamp], @marker_local_create_peer_key = [provision_local_peer_key], @marker_scope_create_peer_timestamp = [provision_scope_peer_timestamp], @marker_scope_create_peer_key = [provision_scope_peer_key], @marker_state = [state]
FROM [DataSync].[provision_marker_dss]
WHERE [object_id] = 1691153070 
 AND [owner_scope_local_id] = 0

DECLARE @marker_update_scope_local_id INT
DECLARE @marker_scope_update_peer_timestamp BIGINT
DECLARE @marker_scope_update_peer_key INT
DECLARE @marker_local_update_peer_timestamp BIGINT
DECLARE @marker_local_update_peer_key INT
SELECT TOP 1 @marker_update_scope_local_id = [provision_scope_local_id], @marker_local_update_peer_timestamp = [provision_timestamp], @marker_local_update_peer_key = [provision_local_peer_key], @marker_scope_update_peer_timestamp = [provision_scope_peer_timestamp], @marker_scope_update_peer_key = [provision_scope_peer_key]
FROM [DataSync].[provision_marker_dss]
WHERE [object_id] = 1691153070 
 AND [owner_scope_local_id] = 1
-- use a temp table to store the list of PKs that successfully got updated
declare @changed TABLE ([Building Number] varchar(3), [Tenant Number] varchar(3), [Date] datetime2, [Line Number] bigint, PRIMARY KEY ([Building Number], [Tenant Number], [Date], [Line Number]));

SET IDENTITY_INSERT [dbo].[pm_Maintenance] ON;
-- update the base table
MERGE [dbo].[pm_Maintenance] AS base USING
-- join done here against the side table to get the local timestamp for concurrency check
(SELECT p.*, t.update_scope_local_id, t.scope_update_peer_key, t.local_update_peer_timestamp FROM @changeTable p LEFT JOIN [DataSync].[pm_Maintenance_dss_tracking] t ON p.[Building Number] = t.[Building Number] AND p.[Tenant Number] = t.[Tenant Number] AND p.[Date] = t.[Date] AND p.[Line Number] = t.[Line Number]) as changes ON changes.[Building Number] = base.[Building Number] AND changes.[Tenant Number] = base.[Tenant Number] AND changes.[Date] = base.[Date] AND changes.[Line Number] = base.[Line Number]
WHEN MATCHED AND (changes.update_scope_local_id = @sync_scope_local_id AND changes.scope_update_peer_key = changes.sync_update_peer_key) OR changes.local_update_peer_timestamp <= @sync_min_timestamp-- No tracking record exists
OR (changes.update_scope_local_id IS NULL AND changes.scope_update_peer_key IS NULL AND changes.local_update_peer_timestamp IS NULL) 
 THEN
UPDATE SET [Description] = changes.[Description], [Vendor] = changes.[Vendor], [Cost] = changes.[Cost], [Inspected] = changes.[Inspected], [clientId] = changes.[clientId]
OUTPUT INSERTED.[Building Number], INSERTED.[Tenant Number], INSERTED.[Date], INSERTED.[Line Number] into @changed; -- populates the temp table with successful PKs

SET IDENTITY_INSERT [dbo].[pm_Maintenance] OFF;
UPDATE side SET
update_scope_local_id = @sync_scope_local_id, 
scope_update_peer_key = changes.sync_update_peer_key, 
scope_update_peer_timestamp = changes.sync_update_peer_timestamp,
local_update_peer_key = 0
FROM 
[DataSync].[pm_Maintenance_dss_tracking] side JOIN 
(SELECT p.[Building Number], p.[Tenant Number], p.[Date], p.[Line Number], p.sync_update_peer_timestamp, p.sync_update_peer_key, p.sync_create_peer_key, p.sync_create_peer_timestamp FROM @changed t JOIN @changeTable p ON p.[Building Number] = t.[Building Number] AND p.[Tenant Number] = t.[Tenant Number] AND p.[Date] = t.[Date] AND p.[Line Number] = t.[Line Number]) as changes ON changes.[Building Number] = side.[Building Number] AND changes.[Tenant Number] = side.[Tenant Number] AND changes.[Date] = side.[Date] AND changes.[Line Number] = side.[Line Number]
SELECT [Building Number], [Tenant Number], [Date], [Line Number] FROM @changeTable t WHERE NOT EXISTS (SELECT [Building Number], [Tenant Number], [Date], [Line Number] from @changed i WHERE t.[Building Number] = i.[Building Number] AND t.[Tenant Number] = i.[Tenant Number] AND t.[Date] = i.[Date] AND t.[Line Number] = i.[Line Number])
END' 
END
GO
