ELSE [base].[ID] END) 
as [ID], 
[base].[Owner Number], [base].[Address 1], [base].[Address 2], [base].[Telephone], [base].[FederalID], [base].[Owner Name], [base].[Billing Name], [base].[email], [base].[clientId], (CASE WHEN [side].[local_create_peer_timestamp] IS NOT NULL 
