declare @changed TABLE ([ID] bigint, PRIMARY KEY ([ID]));

SET IDENTITY_INSERT [dbo].[pm_STTrans] ON;
-- update the base table
MERGE [dbo].[pm_STTrans] AS base USING
-- join done here against the side table to get the local timestamp for concurrency check
(SELECT p.*, t.update_scope_local_id, t.scope_update_peer_key, t.local_update_peer_timestamp FROM @changeTable p LEFT JOIN [DataSync].[pm_STTrans_dss_tracking] t ON p.[ID] = t.[ID]) as changes ON changes.[ID] = base.[ID]
WHEN MATCHED AND (changes.update_scope_local_id = @sync_scope_local_id AND changes.scope_update_peer_key = changes.sync_update_peer_key) OR changes.local_update_peer_timestamp <= @sync_min_timestamp-- No tracking record exists
OR (changes.update_scope_local_id IS NULL AND changes.scope_update_peer_key IS NULL AND changes.local_update_peer_timestamp IS NULL) 
 THEN
UPDATE SET [Building Number] = changes.[Building Number], [Tenant Number] = changes.[Tenant Number], [Sequence Number] = changes.[Sequence Number], [Trans Type] = changes.[Trans Type], [Date] = changes.[Date], [Amount] = changes.[Amount], [clientId] = changes.[clientId]
OUTPUT INSERTED.[ID] into @changed; -- populates the temp table with successful PKs

SET IDENTITY_INSERT [dbo].[pm_STTrans] OFF;
UPDATE side SET
update_scope_local_id = @sync_scope_local_id, 
scope_update_peer_key = changes.sync_update_peer_key, 
scope_update_peer_timestamp = changes.sync_update_peer_timestamp,
local_update_peer_key = 0
FROM 
[DataSync].[pm_STTrans_dss_tracking] side JOIN 
(SELECT p.[ID], p.sync_update_peer_timestamp, p.sync_update_peer_key, p.sync_create_peer_key, p.sync_create_peer_timestamp FROM @changed t JOIN @changeTable p ON p.[ID] = t.[ID]) as changes ON changes.[ID] = side.[ID]
SELECT [ID] FROM @changeTable t WHERE NOT EXISTS (SELECT [ID] from @changed i WHERE t.[ID] = i.[ID])
END' 
END
