(SELECT p.*, t.update_scope_local_id, t.scope_update_peer_key, t.local_update_peer_timestamp FROM @changeTable p LEFT JOIN [DataSync].[pm_Tenants_dss_tracking] t ON p.[Sequence Number] = t.[Sequence Number]) as changes ON changes.[Sequence Number] = base.[Sequence Number]
WHEN MATCHED AND (changes.update_scope_local_id = @sync_scope_local_id AND changes.scope_update_peer_key = changes.sync_update_peer_key) OR changes.local_update_peer_timestamp <= @sync_min_timestamp-- No tracking record exists
OR (changes.update_scope_local_id IS NULL AND changes.scope_update_peer_key IS NULL AND changes.local_update_peer_timestamp IS NULL) 
 THEN
UPDATE SET [Building Number] = changes.[Building Number], [Tenant Number] = changes.[Tenant Number], [Old History File Pointer] = changes.[Old History File Pointer], [New Tenant Flag] = changes.[New Tenant Flag], [Replacing Tenant] = changes.[Replacing Tenant], [Tenant Name] = changes.[Tenant Name], [Apartment] = changes.[Apartment], [Due Date] = changes.[Due Date], [Type] = changes.[Type], [Alternate Billing Address Flag] = changes.[Alternate Billing Address Flag], [Additional Name Flag] = changes.[Additional Name Flag], [Lease Letter Flag] = changes.[Lease Letter Flag], [Low Rent Flag] = changes.[Low Rent Flag], [Legal Code] = changes.[Legal Code], [Legal Code 2] = changes.[Legal Code 2], [Rent] = changes.[Rent], [Security] = changes.[Security], [Arrears] = changes.[Arrears], [Paid] = changes.[Paid], [Future Rent 1] = changes.[Future Rent 1], [Future Rent 2] = changes.[Future Rent 2], [Future Rent 3] = changes.[Future Rent 3], [MBR] = changes.[MBR], [Future Date 1] = changes.[Future Date 1], [Future Date 2] = changes.[Future Date 2], [Future Date 3] = changes.[Future Date 3], [Rooms] = changes.[Rooms], [Square Feet] = changes.[Square Feet], [Move-in Date] = changes.[Move-in Date], [Lease Start Date] = changes.[Lease Start Date], [Lease Expiration Date] = changes.[Lease Expiration Date], [Last Paid Date] = changes.[Last Paid Date], [Additional Name] = changes.[Additional Name], [SSNumber1] = changes.[SSNumber1], [SSNumber2] = changes.[SSNumber2], [HomePhone1] = changes.[HomePhone1], [HomePhone2] = changes.[HomePhone2], [BusPhone1] = changes.[BusPhone1], [BusPhone2] = changes.[BusPhone2], [AltBillName] = changes.[AltBillName], [AltBillAdd1] = changes.[AltBillAdd1], [AltBillAdd2] = changes.[AltBillAdd2], [AltBillAdd3] = changes.[AltBillAdd3], [AddName] = changes.[AddName], [Bank] = changes.[Bank], [InterestInfo] = changes.[InterestInfo], [Shares] = changes.[Shares], [Comment] = changes.[Comment], [Seniorcit] = changes.[Seniorcit], [Total Charges] = changes.[Total Cha