ansientOccupant] = changes.[TransientOccupant], [OwnerOccupied] = changes.[OwnerOccupied], [CommercialProfessional] = changes.[CommercialProfessional], [NotPrimeResidence] = changes.[NotPrimeResidence], [TempExemptOther] = changes.[TempExemptOther], [ExemptDate] = changes.[ExemptDate], [ExemptHighRentVacancy] = changes.[ExemptHighRentVacancy], [ExemptLastLegalPaid] = changes.[ExemptLastLegalPaid], [ExemptHighRentVacanyPeriod] = changes.[ExemptHighRentVacanyPeriod], [ExemptHighRentIncome] = changes.[ExemptHighRentIncome], [ExemptCommercialProfessionalCo] = changes.[ExemptCommercialProfessionalCo], [ExemptSubstantialRehab] = changes.[ExemptSubstantialRehab], [ExemptCoopCondoOwner] = changes.[ExemptCoopCondoOwner], [ExemptSec11243] = changes.[ExemptSec11243], [ExemptOther] = changes.[ExemptOther], [ExemptOtherDesc] = changes.[ExemptOtherDesc], [ExemptExpSec608] = changes.[ExemptExpSec608], [ExemptExp421a] = changes.[ExemptExp421a], [Exempt421aMarketRate] = changes.[Exempt421aMarketRate], [Exempt421aIncome] = changes.[Exempt421aIncome], [Exempt421aMedianIncome] = changes.[Exempt421aMedianIncome], [clientId] = changes.[clientId]
OUTPUT INSERTED.[Sequence Number] into @changed; -- populates the temp table with successful PKs

SET IDENTITY_INSERT [dbo].[pm_Tenants] OFF;
UPDATE side SET
update_scope_local_id = @sync_scope_local_id, 
scope_update_peer_key = changes.sync_update_peer_key, 
scope_update_peer_timestamp = changes.sync_update_peer_timestamp,
local_update_peer_key = 0
FROM 
[DataSync].[pm_Tenants_dss_tracking] side JOIN 
(SELECT p.[Sequence Number], p.sync_update_peer_timestamp, p.sync_update_peer_key, p.sync_create_peer_key, p.sync_create_peer_timestamp FROM @changed t JOIN @changeTable p ON p.[Sequence Number] = t.[Sequence Number]) as changes ON changes.[Sequence Number] = side.[Sequence Number]
SELECT [Sequence Number] FROM @changeTable t WHERE NOT EXISTS (SELECT [Sequence Number] from @changed i WHERE t.[Sequence Number] = i.[Sequence Number])
END' 
