EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [DataSync].[pm_TenantsSnapShot_dss_bulkdelete_f7856053-5d5c-4a36-82ff-3f507b905306]
	@sync_min_timestamp BigInt,
	@sync_scope_local_id Int,
